"""Saved-table Stage 2 report and notebook, with no model scoring or fitting."""
import json
import numpy as np
import pandas as pd
import nbformat
from experiments.independent_audit.report import table


def render(out):
    from .run import ROOT,REPORT,NOTEBOOK,check
    if REPORT.exists() or NOTEBOOK.exists():raise FileExistsError('Refuse replacing an existing report/notebook')
    protocol=json.loads((out/'protocol.json').read_text())
    params=pd.DataFrame(json.loads((out/'calibration_parameters.json').read_text()))
    m=pd.read_csv(out/'monthly_metrics.csv');difference=pd.read_csv(out/'monthly_differences.csv')
    intervals=pd.read_csv(out/'paired_block_intervals.csv');sources=pd.read_csv(out/'score_provenance.csv')
    thresholds=pd.read_csv(out/'selected_thresholds.csv');equivalent=pd.read_csv(out/'equivalent_thresholds.csv')
    raw=m.query("method == 'raw'").set_index(['comparison','base','month'])
    adjusted=m.query("method == 'intercept'").set_index(['comparison','base','month'])
    paired=pd.concat([raw[['prevalence','mean_probability','brier','log_loss','f1','roc_auc','average_precision']].add_prefix('raw_'),
        adjusted[['mean_probability','brier','log_loss','f1','roc_auc','average_precision']].add_prefix('cal_')],axis=1).reset_index()
    paired.to_csv(out/'monthly_comparisons.csv',index=False)
    good_brier=int(difference.brier_calibrated_minus_raw.lt(0).sum())
    good_log=int(difference.log_loss_calibrated_minus_raw.lt(0).sum())
    checks=check(out)
    commands=['LOKY_MAX_CPU_COUNT=2 '+protocol['interpreter']+' -B -m experiments.calibration_study.run '+phase+' --run-id '+out.name for phase in ['start','execute','render','check']]
    parts=['# Stage 2: chronological intercept-only calibration study',
        f'Run `{out.name}`. This study reuses exactly the frozen Stage 1 compact LR F and compact native-categorical histogram boosting G pipelines. No base estimator or preprocessing was refit, no feature or algorithm was added, and no new November–December inference or outcome use occurred. Existing production and previous-stage artifacts remain unchanged.',
        '## Protocol and provenance',
        f'Interpreter: `{protocol["interpreter"]}`. Python: `{protocol["python"]}`. Git commit: `{protocol["git_commit"]}`.',
        table(pd.DataFrame(protocol['versions'].items(),columns=['package','version'])),
        'Initial status, all 208 pre-existing file hashes, input and model hashes, Stage 2 source hashes, parameters and rules were recorded in protocol.json before calibration execution. The before-additions inventory was captured before creating Stage 2 source; the final check verifies these exact original paths rather than modifying Stage 1 checks to ignore new files. Source snapshots also distinguish Stage 2 additions. There was no package upgrade. NumPy/SciPy/joblib/threadpoolctl and notebook tooling remain available through the verified environment; explicit direct dependency declarations are a future task, not a change here.',
        f'Preservation passed for **{checks["protected_file_count"]} pre-existing files**. Stage 1 source, tests, reports, pipeline bytes, protocols, locks and results are all included. Stage 2 adds only experiments/calibration_study/, tests/test_calibration_study.py, this report, its notebook and a unique outputs/experiments/calibration_study/ run directory. Start refuses an existing run; persistent phase markers prevent duplicate execution and no lock is removed.',
        '```text\n'+'\n'.join(commands)+'\n```',
        '## Chronological design and label availability',
        table(pd.DataFrame([{'comparison':key,'frozen_base_fold':value['fold'],'fit_through_month':value['fit_end'],
            'calibration_month':value['calibration'],'threshold_month':value['threshold'],'assessment_months':str(value['assessment'])}
            for key,value in protocol['comparisons'].items()])),
        'Each comparison uses disjoint fit, calibration, threshold and future assessment months. These are reused exploratory periods. August is assessed in comparisons 2 and 3 under different frozen bases/calibrators; it is not independent evidence twice. No average across comparisons is presented as an independent test estimate.',
        'Batch-month assumption: every calibration-month target is available before threshold selection begins, and every threshold-month target is available before assessment begins. This retrospective assumption has not been validated for real-time deployment or label latency.',
        '## Probability methods and controls',
        'Raw probabilities remain exactly as stored/generated by the frozen pipeline. The only learned calibration parameter is an intercept b: expit(logit(p_raw)+b), with slope fixed to 1. The unpenalized binary log-loss derivative is mean(expit(logit(p_raw)+b)) minus observed calibration prevalence; brentq finds its unique finite root with xtol=1e-12. No full sigmoid slope, isotonic fit, class weights, rolling update or calibration search is used.',
        'Numerical convention: clip probabilities to [1e-12,1−1e-12] only for calibration logits and log-loss evaluation; retain raw probabilities unchanged for raw Brier/ranking/classification. Use log1p/logaddexp and scipy.special.expit. An all-one/all-zero calibration target has no finite unconstrained optimum and is explicitly rejected; all actual calibration periods contain both classes. Clipping can create ties at extreme endpoints; observed AUC/AP changes and equivalent-threshold boundary counts are audited.',
        'Constant controls use either the base-training-month observed prevalence or calibration-month observed prevalence. Neither uses threshold or assessment outcomes. Controls use threshold 0.5 only for descriptive classification columns; they are primarily probability-level references.',
        '## Saved score reuse and frozen-base integrity',
        table(sources),
        f'Total reused score rows: {sources.reused_n.sum():,}; generated missing development rows: {sources.generated_n.sum():,}. Generation uses only missing IDs for the same frozen base pipeline and never enters November–December. Date/target/ID alignment is checked before cache reuse. Raw scores for calibration, threshold and assessment periods are saved in raw_period_scores.csv.',
        table(pd.read_csv(out/'base_integrity.csv')[['comparison','base','unchanged','base_fit_calls']]),
        'Every loaded base is byte-hashed on disk and joblib-hashed in memory before/after scoring. Both hashes must remain unchanged. Stage 2 does not call fit on a base pipeline; calibration parameters are saved separately as JSON.',
        '## Fitted intercepts and fit dates',
        table(params[['comparison','base','base_fit_last_date','calibration_first_date','calibration_last_date','intercept','prevalence','calibrated_mean','gradient','training_prior']]),
        'On each calibration month the fitted mean probability matches its observed prevalence, as the first-order condition requires. This is calibration-month fit, not evidence of transfer to a later month.',
        '## All monthly future probability comparisons',
        table(paired[['comparison','base','month','raw_prevalence','raw_mean_probability','cal_mean_probability','raw_brier','cal_brier','raw_log_loss','cal_log_loss']]),
        table(difference[['comparison','base','month','brier_calibrated_minus_raw','log_loss_calibrated_minus_raw']]),
        f'Negative differences favor calibration. Brier improves in {good_brier} of {len(difference)} model/comparison/month cells and log loss in {good_log} of {len(difference)}. These counts include correlated models and repeated August assessments; they are descriptive counts, not independent trials or a pooled efficacy estimate.',
        'Mean prediction error is mean probability minus observed prevalence (positive means overprediction). Reliability bins include their sample sizes in monthly_reliability.csv and the notebook. Proper scores assess overall probability quality, not only calibration; mean agreement alone does not establish individual-risk reliability.',
        table(m[['comparison','base','method','month','n','prevalence','mean_probability','mean_prediction_error','brier','log_loss','roc_auc','average_precision']]),
        '## Threshold selection and discrimination',
        table(thresholds),
        'Each raw/calibrated method chooses its threshold independently on the designated threshold month only: fixed 0.10–0.50 grid, step 0.025, maximum F1 with ties closest to 0.5 then higher. Selected thresholds remain unchanged during assessment. Tune-only curves are in threshold_curves.csv; no assessment outcome chooses an operating point.',
        table(m.loc[m.method.isin(['raw','intercept']),['comparison','base','method','month','threshold','precision','recall','f1','accuracy','tn','fp','fn','tp']]),
        table(paired[['comparison','base','month','raw_roc_auc','cal_roc_auc','raw_average_precision','cal_average_precision','raw_f1','cal_f1']]),
        'An increasing intercept shift preserves ranking. Actual AUC/AP equality is checked from saved rows; F1 differences after independent grid selection reflect operating-point/grid selection, not improved discrimination. The two grids have the same numeric values but represent different raw-scale thresholds after adjustment.',
        '### Equivalent-threshold diagnostic',table(equivalent),
        'Map the raw chosen threshold through the fitted transformation, then compare raw and calibrated classifications on exactly the same assessment IDs. Any mismatch farther than absolute 1e-12 from both threshold boundaries is an error; documented floating-point boundary rows are counted separately. This directly distinguishes probability-level changes from a change in ranking or classification at corresponding cutoffs.',
        '## Paired seven-calendar-day uncertainty',table(intervals),
        'Intervals use 500 replicates, seed 42, with fitted probabilities, intercepts and thresholds held fixed. Seven-consecutive-calendar-day blocks are sampled from valid noncircular starts, concatenated/truncated to original calendar length; the same day weights apply to raw and calibrated losses. Each assessment month is reported separately. Comparison 2 also has a combined July–August diagnostic within that comparison only.',
        'Percentile intervals condition on previously fitted bases/calibrators and do not correct reused periods, earlier selection, overlapping comparisons, nonstationarity, or all seasonal dependence. Endpoint days have fewer moving-block memberships. Negative calibrated-minus-raw loss differences indicate improvement; do not infer broad deployment validity from a narrow conditional interval.',
        '## Assessment and review boundary',
        'Use the monthly table and paired intervals to judge transfer rather than calibration-month fit. A single global offset can follow yesterday’s prevalence in the wrong direction when disruption levels change. An improvement in October alone is not proof that the same update works throughout summer.',
        ('Recommendation: retain raw scores with explicit probability-quality limitations; do not adopt a universal intercept update. Gains do not transfer consistently across the prescribed periods.' if good_brier<len(difference) or good_log<len(difference) else
         'Recommendation: results support further review of intercept adjustment, but this reused exploratory evidence is insufficient for automatic production adoption.'),
        'No model integration, dashboard, next stage, commit or push is performed. Any follow-up requires a separately reviewed decision; do not use the old November–December outcomes to select this method.',
        '## Verification and tests',
        'Every reported metric is recalculated from assessment_predictions.csv. Calibration parameters, period dates, raw period scores, tune-only curves, thresholds, equivalent decisions, score provenance, reliability bins, paired bootstrap draws and base-integrity checks are retained. The Stage 2 tests cover chronological separation, metadata/outcome isolation, intercept optimum and boundary cases, finite probabilities, monotonicity, equivalent threshold decisions, missing-only score generation, no base fit calls, deterministic bootstrap and protected-file mutation detection. Existing tests run unchanged.',
        'Test command: `LOKY_MAX_CPU_COUNT=2 '+protocol['interpreter']+' -B -m unittest discover -s tests -v`. Final test execution details are recorded in execution_validation.json. The saved-output notebook only reads tables and produces displayed figures; it never trains, calibrates, predicts or writes study tables.'
    ]
    REPORT.write_text('\n\n'.join(parts)+'\n')
    create_notebook(NOTEBOOK,out,ROOT)


def create_notebook(path,out,root):
    md=nbformat.v4.new_markdown_cell;code=nbformat.v4.new_code_cell
    n=nbformat.v4.new_notebook()
    n.cells=[md('''# Stage 2: chronological calibration of frozen compact models

Read saved outputs only: no model loading, inference, fitting, recalibration or table writes. These are reused retrospective development periods with batch-month label availability. No November–December results are used.

The full report is `reports/chronological_calibration_study.md`.'''),
    code(f'''from pathlib import Path
import json
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display
ROOT=Path.cwd()
if not (ROOT/'experiments/calibration_study').exists(): ROOT=ROOT.parent
OUT=ROOT/{out.relative_to(root).as_posix()!r}
m=pd.read_csv(OUT/'monthly_metrics.csv')
comparisons=pd.read_csv(OUT/'monthly_comparisons.csv')
params=pd.DataFrame(json.loads((OUT/'calibration_parameters.json').read_text()))
print('Run:',OUT.name)
display(params[['comparison','base','base_fit_last_date','calibration_first_date','calibration_last_date','intercept','prevalence','calibrated_mean']])
display(pd.read_csv(OUT/'score_provenance.csv'))'''),
    md('## Future probability levels and primary loss outcomes\nEvery cell compares the same flights and frozen base pipeline. Negative calibrated-minus-raw losses favor calibration. Repeated August assessments are not independent evidence.'),
    code('''display(comparisons)
display(m[['comparison','base','method','month','n','prevalence','mean_probability','mean_prediction_error','brier','log_loss','roc_auc','average_precision']])
fig,axes=plt.subplots(1,2,figsize=(14,5))
for ax,base in zip(axes,['F','G']):
    g=comparisons.loc[comparisons.base.eq(base)]
    x=range(len(g));labels=[f'{r.comparison}: month {r.month}' for r in g.itertuples()]
    ax.plot(x,g.raw_prevalence,'k--o',label='Observed')
    ax.plot(x,g.raw_mean_probability,'o-',label='Raw')
    ax.plot(x,g.cal_mean_probability,'o-',label='Intercept')
    ax.set(title=f'Frozen base {base}',xticks=list(x),xticklabels=labels,ylabel='Mean probability / prevalence')
    ax.tick_params(axis='x',rotation=25);ax.legend()
plt.tight_layout();plt.show()'''),
    md('## Reliability and bin counts\nIntercept fitting matches the calibration-month mean by construction. The diagrams below use later assessment labels; mean agreement and ranking alone do not establish calibrated individual risk.'),
    code('''bins=pd.read_csv(OUT/'monthly_reliability.csv')
fig,axes=plt.subplots(2,2,figsize=(13,9))
for row,base in enumerate(['F','G']):
    for col,method in enumerate(['raw','intercept']):
        ax=axes[row,col]
        for (comparison,month),g in bins.loc[bins.base.eq(base)&bins.method.eq(method)].groupby(['comparison','month']):
            ax.plot(g.mean_probability,g.observed_rate,'.-',label=f'{comparison}: month {month}')
        ax.plot([0,1],[0,1],'k--');ax.set(title=f'{base} {method}',xlabel='Mean predicted probability',ylabel='Observed frequency');ax.legend(fontsize=7)
plt.tight_layout();plt.show()
display(bins)
# Counts remain visible rather than treating sparse high-risk bins as equally reliable.
fig,ax=plt.subplots(figsize=(11,4))
for (base,method),g in bins.loc[bins.comparison.eq(4)].groupby(['base','method']):
    ax.plot(g.mean_probability,g.n,'.-',label=f'{base} {method}')
ax.set(title='October reliability-bin counts',xlabel='Mean predicted probability',ylabel='Flights',yscale='log');ax.legend();plt.show()'''),
    md('## Classification is an operating-point diagnostic\nSeparate raw/calibrated thresholds come only from their designated earlier threshold month. Offsetting cannot improve ranking; a changed F1 on the fixed numeric grid is an operating-point effect. Corresponding transformed thresholds should preserve classifications.'),
    code('''display(pd.read_csv(OUT/'selected_thresholds.csv'))
display(m.loc[m.method.isin(['raw','intercept']),['comparison','base','method','month','threshold','precision','recall','f1','accuracy','tn','fp','fn','tp']])
display(pd.read_csv(OUT/'equivalent_thresholds.csv'))
print('Maximum absolute AUC/AP differences:')
diff=pd.read_csv(OUT/'monthly_differences.csv')
display(diff[['roc_auc_calibrated_minus_raw','average_precision_calibrated_minus_raw']].abs().max())'''),
    md('## Paired uncertainty\n500 seven-calendar-day moving-block replicates, fixed fitted scores/intercepts. Intervals do not account for all temporal dependence, overlapping periods or prior selection. Comparison 2 pooled intervals are only a within-comparison diagnostic.'),
    code('''intervals=pd.read_csv(OUT/'paired_block_intervals.csv')
display(intervals)
monthly=intervals.loc[intervals.assessment_scope.ne('combined_within_comparison')]
fig,axes=plt.subplots(1,2,figsize=(15,7))
for ax,metric in zip(axes,['brier','log_loss']):
    g=monthly.loc[monthly.metric.eq(metric)].reset_index(drop=True)
    labels=[f'{r.comparison}/{r.base}/month {r.assessment_scope}' for r in g.itertuples()]
    for i,r in g.iterrows():
        ax.plot([r.ci_low,r.ci_high],[i,i],color='steelblue');ax.plot(r.difference,i,'ko')
    ax.axvline(0,color='gray',linestyle='--');ax.set(title=f'Calibrated minus raw {metric}',yticks=range(len(g)),yticklabels=labels)
plt.tight_layout();plt.show()'''),
    md('## Review boundary\nRead the report’s recommendation across all periods. No production model, Stage 1 artifact or previous finding is modified. No universal calibration rule or real-time deployment claim follows from these reused comparisons.'),
    code('''display(pd.read_csv(OUT/'base_integrity.csv')[['comparison','base','unchanged','base_fit_calls']])
print('This notebook reads saved outputs only. No model inference or fitting was performed.')''')]
    n.metadata={'kernelspec':{'display_name':'Python 3 (verified environment)','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.13.13'}}
    nbformat.write(n,path)
